# lm50 Tokyo phase 1: the hand-picked target table (read by ty50_targets.py, which resolves every row against current OSM and the
# app's staged map data and writes targets_ty.json).
# T(group, key, zh, en, kind, osm, h, hs, note, unc='', hero=False)
#   osm  'w123' / 'r123' = the OSM building (or bridge area) the anchor sits on; 'a:w123' = a precinct / site area: the resolver
#        anchors on the largest building inside it and says so in unc.
#   h    verified overall height in m (or None) — hs says what was checked and where (URL). Heights from OSM tags are NOT counted as
#        verified: the resolver adds them to hs as "OSM height tag (PLATEAU / mapper value, not verified)".
#   note recognition hint for the modeller (not a verified spec unless hs says so).
W1 = 'https://en.wikipedia.org/wiki/List_of_tallest_buildings_in_Tokyo (table, checked 2026-11-27)'
W2 = 'https://en.wikipedia.org/wiki/List_of_tallest_buildings_in_Yokohama (table, checked 2026-11-27)'
ROWS = []
def T(group, key, zh, en, kind, osm, h, hs, note, unc='', hero=False):
    ROWS.append(dict(group=group, key=key, zh=zh, en=en, kind=kind, osm=osm, h=h, hs=hs, note=note, unc=unc, hero=hero))
def W(h, f, y): return '%s m, %s floors, %s — %s' % (h, f, y, W1)
def WY(h, f, y): return '%s m, %s floors, %s — %s' % (h, f, y, W2)

